import 'package:flutter/material.dart'; import '../../core/api.dart'; import '../../core/models.dart';
import '../../core/progress.dart';
import 'continue_watching.dart';
import '../watch/watch_page.dart';
import '../details/details_page.dart';
class HomePage extends StatefulWidget{const HomePage({super.key,required this.api});final ApiClient api;@override State<HomePage> createState()=>_HomePageState();}
class _HomePageState extends State<HomePage>{late Future<List<TitleItem>> future;@override void initState(){super.initState();future=widget.api.home();}Widget image(String u,{double? w})=>u.startsWith('http')?Image.network(u,fit:BoxFit.cover,width:w,errorBuilder:(_,__,___)=>const Center(child:Icon(Icons.broken_image))):Image.asset(u,fit:BoxFit.cover,width:w,errorBuilder:(_,__,___)=>const Center(child:Icon(Icons.image_not_supported)));Widget card(TitleItem x)=>InkWell(onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>DetailsPage(title:x,api:widget.api))),child:Card(clipBehavior:Clip.antiAlias,child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Expanded(child:image(x.image,w:double.infinity)),Padding(padding:const EdgeInsets.all(9),child:Text(x.name,maxLines:1,overflow:TextOverflow.ellipsis,style:const TextStyle(fontWeight:FontWeight.w700))),if(x.subtitle.isNotEmpty)Padding(padding:const EdgeInsets.fromLTRB(9,0,9,9),child:Text(x.subtitle,maxLines:1,overflow:TextOverflow.ellipsis))])));
@override Widget build(BuildContext context)=>RefreshIndicator(onRefresh:()async{setState(()=>future=widget.api.home());},child:CustomScrollView(slivers:[SliverAppBar(pinned:true,title:Image.asset('assets/images/common/anivortex_logo_transparent.png',height:34)),SliverToBoxAdapter(child:ContinueWatching(onTap:(x){final t=TitleItem(id:x.titleId,name:x.title);Navigator.push(context,MaterialPageRoute(builder:(_)=>WatchPage(api:widget.api,title:t,episode:EpisodeItem(id:'${x.titleId}-e${x.episode}',number:x.episode)));})),SliverToBoxAdapter(child:Padding(padding:const EdgeInsets.fromLTRB(16,18,16,10),child:Text('New movie, series, and anime updates',style:Theme.of(context).textTheme.titleLarge))),SliverPadding(padding:const EdgeInsets.all(12),sliver:FutureBuilder<List<TitleItem>>(future:future,builder:(c,s){if(s.connectionState==ConnectionState.waiting)return const SliverFillRemaining(child:Center(child:CircularProgressIndicator()));final a=s.data??demoTitles;return SliverGrid.builder(gridDelegate:const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:2,childAspectRatio:.68,crossAxisSpacing:10,mainAxisSpacing:10),itemCount:a.length,itemBuilder:(_,i)=>card(a[i]));}))]));}
